      const effBB = Math.min(player.stack + player.bet, raiser.stack + raiser.bet) / bb;
      if (effBB < HU_BB_MIN_STACK_BB || effBB > HU_BB_MAX_STACK_BB) return undefined;
      const cls = holdemClass(player.cards[0], player.cards[1]);
