      opts.v56OmahaPressureRange !== false &&
      !isTournamentMode(gs) &&
      ['plo4', 'plo5', 'plo6'].includes(gs.gameVariant) &&
      isRiver &&
      extraBoards.length === 0 &&
      !vi.isHiLo &&
      !vi.isFixedLimit &&
      oppReads
